dashboard.definition:
{
    "dataSources": {
        "ds_deprecations": {
            "name": "ds_deprecations",
            "options": {
                "query": "`index_nifi` sourcetype=\"nifi:log:deprecation\" host=\"$host$\"\n| rex \"\\]\\s+(?<logger>\\S+)\\s+(?<message>[^\\r\\n]+)\"\n| eval message = substr(message, 1, 240)\n| stats count as Occurrences, latest(_time) as last by host logger message\n| eval \"Last seen\" = strftime(last, \"%Y-%m-%d %H:%M\") | sort - Occurrences\n| table host logger message Occurrences \"Last seen\"\n| rename host as Instance, logger as Logger, message as Message",
                "queryParameters": {
                    "earliest": "-7d@d",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_events": {
            "name": "ds_events",
            "options": {
                "query": "`index_nifi` sourcetype=\"nifi:log:app\" host=\"$host$\" level=\"$level$\" $search$\n| head 50 | eval Time = strftime(_time, \"%Y-%m-%d %H:%M:%S\") | table Time host level _raw | rename host as Instance, level as Level, _raw as Event",
                "queryParameters": {
                    "earliest": "$time.earliest$",
                    "latest": "$time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_input_host": {
            "name": "Choices for Instance",
            "options": {
                "query": "| tstats count where `index_nifi` sourcetype=nifi:log:* by host | fields host",
                "queryParameters": {
                    "earliest": "-24h@h",
                    "latest": "now"
                }
            },
            "type": "ds.search"
        },
        "ds_levels": {
            "name": "ds_levels",
            "options": {
                "query": "| tstats count from datamodel=NIFI.Logs where host=\"$host$\" Logs.level=\"$level$\" by _time Logs.level span=5m\n| rename Logs.level as level | timechart span=5m sum(count) by level",
                "queryParameters": {
                    "earliest": "$time.earliest$",
                    "latest": "$time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_req_class": {
            "name": "ds_req_class",
            "options": {
                "query": "| tstats count from datamodel=NIFI.Request_Log where host=\"$host$\" by _time Request_Log.status span=5m\n| eval class = substr('Request_Log.status', 1, 1) . \"xx\"\n| timechart span=5m sum(count) by class",
                "queryParameters": {
                    "earliest": "$time.earliest$",
                    "latest": "$time.latest$"
                }
            },
            "type": "ds.search"
        },
        "ds_req_top": {
            "name": "ds_req_top",
            "options": {
                "query": "| tstats count from datamodel=NIFI.Request_Log where host=\"$host$\" Request_Log.status>=400\n  by Request_Log.user Request_Log.uri_path Request_Log.status\n| rename Request_Log.* as * | sort - count | head 10\n| rename user as User, uri_path as URI, status as Status, count as Count",
                "queryParameters": {
                    "earliest": "$time.earliest$",
                    "latest": "$time.latest$"
                }
            },
            "type": "ds.search"
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$time.earliest$",
                        "latest": "$time.latest$"
                    }
                }
            }
        }
    },
    "description": "Application log, deprecations and API requests",
    "inputs": {
        "input_host": {
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "label": ">primary | seriesByName(\"host\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "value": ">primary | seriesByName(\"host\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            },
            "dataSources": {
                "primary": "ds_input_host"
            },
            "options": {
                "defaultValue": "*",
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "host"
            },
            "title": "Instance",
            "type": "input.dropdown"
        },
        "input_level": {
            "options": {
                "defaultValue": "*",
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "ERROR",
                        "value": "ERROR"
                    },
                    {
                        "label": "WARN",
                        "value": "WARN"
                    },
                    {
                        "label": "INFO",
                        "value": "INFO"
                    }
                ],
                "token": "level"
            },
            "title": "Severity",
            "type": "input.dropdown"
        },
        "input_search": {
            "options": {
                "defaultValue": "*",
                "token": "search"
            },
            "title": "Search",
            "type": "input.text"
        },
        "input_time": {
            "options": {
                "defaultValue": "-60m@m,now",
                "token": "time"
            },
            "title": "Time range",
            "type": "input.timerange"
        }
    },
    "layout": {
        "globalInputs": [
            "input_time",
            "input_host",
            "input_level",
            "input_search"
        ],
        "options": {
            "height": 1120,
            "width": 1440
        },
        "structure": [
            {
                "item": "viz_app",
                "position": {
                    "h": 40,
                    "w": 1440,
                    "x": 0,
                    "y": 0
                },
                "type": "block"
            },
            {
                "item": "viz_levels",
                "position": {
                    "h": 340,
                    "w": 600,
                    "x": 0,
                    "y": 40
                },
                "type": "block"
            },
            {
                "item": "viz_events",
                "position": {
                    "h": 340,
                    "w": 840,
                    "x": 600,
                    "y": 40
                },
                "type": "block"
            },
            {
                "item": "viz_dep",
                "position": {
                    "h": 70,
                    "w": 1440,
                    "x": 0,
                    "y": 380
                },
                "type": "block"
            },
            {
                "item": "viz_deprecations",
                "position": {
                    "h": 300,
                    "w": 1440,
                    "x": 0,
                    "y": 450
                },
                "type": "block"
            },
            {
                "item": "viz_req",
                "position": {
                    "h": 70,
                    "w": 1440,
                    "x": 0,
                    "y": 750
                },
                "type": "block"
            },
            {
                "item": "viz_req_class",
                "position": {
                    "h": 300,
                    "w": 720,
                    "x": 0,
                    "y": 820
                },
                "type": "block"
            },
            {
                "item": "viz_req_top",
                "position": {
                    "h": 300,
                    "w": 720,
                    "x": 720,
                    "y": 820
                },
                "type": "block"
            }
        ],
        "type": "grid"
    },
    "title": "Logs",
    "visualizations": {
        "viz_app": {
            "options": {
                "fontSize": "default",
                "markdown": "### Application"
            },
            "type": "splunk.markdown"
        },
        "viz_dep": {
            "options": {
                "fontSize": "default",
                "markdown": "### Deprecations\nWhat this NiFi uses that a later version removes: the list to clear before moving to NiFi 2.x. Needs the nifi-deprecation.log monitor enabled."
            },
            "type": "splunk.markdown"
        },
        "viz_deprecations": {
            "context": {
                "tableHeaderBackgroundColorConfig": {
                    "channel": "rgb",
                    "value": "#E1E0D9"
                },
                "tableRowColorMaxContrast": {
                    "maximum": "#0B0B0B",
                    "minimum": "#FFFFFF"
                }
            },
            "dataSources": {
                "primary": "ds_deprecations"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "showInternalFields": false,
                "tableFormat": {
                    "headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
                    "headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
                    "rowBackgroundColors": "> table | seriesByIndex(0) | noRecolor()",
                    "rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
                }
            },
            "title": "Deprecated usage · last 7 days",
            "type": "splunk.table"
        },
        "viz_events": {
            "context": {
                "LevelRowColorsEditorConfig": [
                    {
                        "match": "ERROR",
                        "value": "#D03B3B"
                    },
                    {
                        "match": "WARNING",
                        "value": "#FAB219"
                    },
                    {
                        "match": "WARN",
                        "value": "#FAB219"
                    },
                    {
                        "match": "INFO",
                        "value": "#9A9890"
                    }
                ],
                "tableHeaderBackgroundColorConfig": {
                    "channel": "rgb",
                    "value": "#E1E0D9"
                },
                "tableRowColorMaxContrast": {
                    "maximum": "#0B0B0B",
                    "minimum": "#FFFFFF"
                }
            },
            "dataSources": {
                "primary": "ds_events"
            },
            "description": "nifi-app.log, newest first, matching the search",
            "options": {
                "backgroundColor": "transparent",
                "columnFormat": {
                    "Event": {
                        "width": 650
                    },
                    "Level": {
                        "rowColors": "> table | seriesByName(\"Level\") | matchValue(LevelRowColorsEditorConfig)"
                    }
                },
                "count": 8,
                "headerVisibility": "fixed",
                "showInternalFields": false,
                "tableFormat": {
                    "headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
                    "headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
                    "rowBackgroundColors": "> table | seriesByIndex(0) | noRecolor()",
                    "rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
                }
            },
            "title": "Events",
            "type": "splunk.table"
        },
        "viz_levels": {
            "dataSources": {
                "primary": "ds_levels"
            },
            "description": "Structured filters only; the search box applies to the events",
            "options": {
                "legendDisplay": "bottom",
                "seriesColors": [
                    "#2A78D6",
                    "#EB6834",
                    "#1BAF7A",
                    "#EDA100"
                ],
                "seriesColorsByField": {
                    "ERROR": "#D03B3B",
                    "INFO": "#9A9890",
                    "WARN": "#FAB219",
                    "WARNING": "#FAB219"
                },
                "showRoundedY2AxisLabels": false,
                "showSplitSeries": false,
                "stackMode": "stacked",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            },
            "title": "Events by level",
            "type": "splunk.column"
        },
        "viz_req": {
            "options": {
                "fontSize": "default",
                "markdown": "### API requests\nFrom nifi-request.log: who calls NiFi's API and what fails."
            },
            "type": "splunk.markdown"
        },
        "viz_req_class": {
            "dataSources": {
                "primary": "ds_req_class"
            },
            "description": "5-minute buckets",
            "options": {
                "legendDisplay": "bottom",
                "seriesColors": [
                    "#2A78D6",
                    "#EB6834",
                    "#1BAF7A",
                    "#EDA100"
                ],
                "seriesColorsByField": {
                    "2xx": "#2A78D6",
                    "3xx": "#1BAF7A",
                    "4xx": "#FAB219",
                    "5xx": "#D03B3B"
                },
                "showRoundedY2AxisLabels": false,
                "showSplitSeries": false,
                "stackMode": "stacked",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            },
            "title": "Requests by status class",
            "type": "splunk.column"
        },
        "viz_req_top": {
            "context": {
                "tableHeaderBackgroundColorConfig": {
                    "channel": "rgb",
                    "value": "#E1E0D9"
                },
                "tableRowColorMaxContrast": {
                    "maximum": "#0B0B0B",
                    "minimum": "#FFFFFF"
                }
            },
            "dataSources": {
                "primary": "ds_req_top"
            },
            "description": "4xx and 5xx",
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "showInternalFields": false,
                "tableFormat": {
                    "headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
                    "headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)",
                    "rowBackgroundColors": "> table | seriesByIndex(0) | noRecolor()",
                    "rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)"
                }
            },
            "title": "Top failing requests",
            "type": "splunk.table"
        }
    }
}
